var e={"vmode.on":`Sprachmodus: sprich laut mit Harness`,"vmode.off":`Auflegen`,"vmode.connecting":`Verbinde`,"vmode.listening":`Ich höre zu`,"vmode.hearing":`Ich höre dich`,"vmode.thinking":`Denke nach`,"vmode.speaking":`Spricht`,"vmode.paused":`Pausiert`,"vmode.working":`Claude arbeitet`,"vmode.tapSkip":`Tippen, damit es aufhört zu sprechen`,"vmode.you":`Du`,"vmode.voice":`Harness`,"vmode.notReady":`Richte zuerst den Sprachmodus ein (Einstellungen -> Sprache)`,"vmode.failed":`Sprachmodus`,"vmode.btn.card":`Schaltflächen des Nachrichtenfelds`,"vmode.btn.cardDesc":`Blende aus, was du nicht nutzt: Die Schaltflächen verschwinden in jedem Nachrichtenfeld auf allen Geräten.`,"vmode.btn.mic":`Mikrofon-Schaltfläche`,"vmode.btn.micDesc":`Diktat und Sprachnachrichten.`,"vmode.btn.call":`Schaltfläche für den Sprachmodus`,"vmode.btn.callDesc":`Laut mit Harness sprechen.`,"vmode.card":`Sprachmodus`,"vmode.cardDesc":`Sprich laut mit Harness: Eine Stimme antwortet dir, übergibt die eigentliche Arbeit mit deinen eigenen Worten an die Sitzung (dasselbe Claude, dieselben Dateien und Tools) und sagt dir das Ergebnis. Schaltfläche in der Leiste einer Sitzung.`,"vmode.set.local":`Auf diesem Server`,"vmode.set.localDesc":`Kostenlos und privat: die Transkription aus Einstellungen -> Sprache, ein Claude-Modell als Stimme, Piper zum Sprechen.`,"vmode.set.cloud":`Cloud (Echtzeit)`,"vmode.set.cloudDesc":`Ein Echtzeit-Sprachmodell von OpenAI oder Gemini: antwortet in unter einer Sekunde, klingt natürlich, du kannst ihm ins Wort fallen. Etwa 1 bis 5 Cent pro Minute über deinen Schlüssel; das Audio geht an diesen Anbieter.`,"vmode.set.ready":`Bereit`,"vmode.set.needStt":`Aktiviere oben die Sprachnachrichten (beliebige Engine): Die lokale Stimme nutzt sie, um dich zu verstehen.`,"vmode.set.needTts":`Die lokale Stimme ist nicht installiert`,"vmode.set.needTtsDesc":`Piper und zwei Stimmen (Französisch, Englisch): etwa 150 MB, eine Minute.`,"vmode.set.install":`Installieren`,"vmode.set.talker":`Modell der Stimme`,"vmode.set.silence":`Pause vor dem Ende deines Satzes`,"vmode.set.silenceDesc":`Wie lange eine Stille dauert, bevor die Stimme sie als Ende deiner Äußerung wertet.`,"vmode.set.talkerDesc":`Es spricht mit dir und entscheidet, wann die Sitzung arbeitet: Sonnet entscheidet besser, Haiku antwortet schneller.`,"vmode.set.haiku":`Haiku (schnell)`,"vmode.set.sonnet":`Sonnet (empfohlen)`,"vmode.set.voice":`Stimme`,"vmode.set.localVoiceDesc":`Wird verwendet, wenn die Stimme ihre Sprache spricht (eine andere Sprache hat ihre eigene Stimme). ↓ = wird bei Auswahl heruntergeladen.`,"vmode.set.auto":`Automatisch`,"vmode.set.speed":`Geschwindigkeit`,"vmode.set.speedDesc":`Wie schnell die lokale Stimme spricht.`,"vmode.set.speed1":`Ruhig`,"vmode.set.speed115":`Normal`,"vmode.set.speed13":`Schnell`,"vmode.set.speed145":`Sehr schnell`,"vmode.set.chooseProvider":`Du hast einen Schlüssel für OpenAI und für Gemini: Wähle den, der genutzt werden soll.`,"vmode.set.keyFound":`Schlüssel gefunden`,"vmode.set.noKey":`Kein Schlüssel`,"vmode.set.openaiDesc":`OpenAI Realtime über WebRTC. Sehr natürliche Stimmen.`,"vmode.set.geminiDesc":`Gemini Live. Am günstigsten, in vielen Sprachen sehr gut.`,"vmode.set.key":`Schlüssel`,"vmode.set.keyDesc":`Im Schlüssel-Tresor gespeichert; der Browser erhält nur ein Token, das für einen Anruf gilt.`,"vmode.set.keyChoose":`Mehrere Schlüssel im Tresor gefunden: Wähle den, der genutzt werden soll.`,"vmode.set.keyPick":`Schlüssel wählen`,"vmode.set.model":`Modell`,"vmode.set.modelDesc":`Ändere es, wenn der Anbieter ein neues veröffentlicht.`,"vmode.set.privacy":`Dein Schlüssel verlässt diesen Server nie: Jeder Anruf erhält ein kurzlebiges Token mit fest eingestellten Anweisungen.`};export{e as default};